"""Preview-only §E v11.61 contextual operation + native-input companion.
No mutations to the protected source manifest, model data or deployment trigger.
The companion is opt-in through the existing dock's Context button.
"""
CSS = "\n/* §E 11.61 contextual tool companion. Existing inspector/controls remain intact. */\n.model-atelier .atelier-context-workbench[hidden]{display:none!important}\n.model-atelier .atelier-context-workbench{position:fixed;z-index:2160;right:66px;top:86px;width:min(660px,calc(100vw - 86px));height:min(72dvh,660px);max-height:calc(100dvh - 110px);background:#17243bed;border:1px solid #78a7ca;border-radius:14px;color:#ecf5ff;box-shadow:0 15px 38px #000b;display:flex;flex-direction:column;overflow:hidden}\n.model-atelier .atelier-context-header{touch-action:none;cursor:grab;user-select:none;background:#263b59;min-height:43px;display:flex;align-items:center;justify-content:space-between;padding:5px 9px;gap:8px}\n.model-atelier .atelier-context-header>div{display:flex;gap:4px}\n.model-atelier .atelier-context-header button,.model-atelier #atelierContextToggle{font-size:11px;min-height:30px;padding:4px 8px}\n.model-atelier .atelier-context-title{display:flex;flex-direction:column;background:#182c48;border-bottom:1px solid #456b90;padding:5px 10px}\n.model-atelier .atelier-context-title span{font-size:10px;color:#b9d4e5;overflow-wrap:anywhere}\n.model-atelier .atelier-context-body{display:grid;grid-template-columns:minmax(130px,38%) minmax(0,1fr);min-height:0;flex:1}\n.model-atelier .atelier-context-left,.model-atelier .atelier-context-right{min-height:0;overflow-y:auto;overscroll-behavior:contain;padding:10px}\n.model-atelier .atelier-context-left{background:#152135;border-right:1px solid #3e617d}\n.model-atelier .atelier-context-left label{font-size:11px;display:block;margin-bottom:4px}\n.model-atelier #atelierContextFind{min-width:0;width:100%;font-size:12px;margin-bottom:8px}\n.model-atelier #atelierContextOperations{display:flex;flex-direction:column;gap:5px}\n.model-atelier .atelier-context-op{width:100%;text-align:left;font-size:12px;min-height:36px;white-space:normal;overflow-wrap:anywhere}\n.model-atelier .atelier-context-op[aria-pressed=true]{background:#166e76;border-color:#79eee1}\n.model-atelier .atelier-context-right>strong{font-size:14px}\n.model-atelier .atelier-context-right>p{font-size:11px;color:#b1cadf}\n.model-atelier #atelierContextFields{display:grid;grid-template-columns:repeat(auto-fit,minmax(145px,1fr));gap:8px;margin-top:8px}\n.model-atelier .atelier-context-field{display:flex;flex-direction:column;gap:4px;min-width:0}\n.model-atelier .atelier-context-field label{color:#cae3f8;font-size:11px;line-height:1.3;overflow-wrap:anywhere}\n.model-atelier .atelier-context-field input,.model-atelier .atelier-context-field select,.model-atelier .atelier-context-field textarea{width:100%;min-width:0;max-width:100%;font-size:13px}\n.model-atelier .atelier-context-field button{white-space:normal;min-height:38px;font-size:12px}\n.model-atelier .atelier-context-preset{display:flex;gap:7px;flex-wrap:wrap;margin-top:10px}\n.model-atelier .atelier-context-preset button{font-size:11px}\n.model-atelier #atelierContextFeedback{font-size:11px}\n.model-atelier .atelier-context-workbench :is(button,input,select,textarea):focus-visible{outline:2px solid #78f6e8;outline-offset:2px}\n@media(max-width:700px),(pointer:coarse){\n .model-atelier .atelier-context-workbench{top:auto;bottom:50px;right:58px;width:calc(100vw - 66px);height:min(62dvh,590px);max-height:calc(100dvh - 105px)}\n .model-atelier .atelier-context-body{grid-template-columns:minmax(112px,39%) minmax(0,1fr)}\n .model-atelier .atelier-context-left,.model-atelier .atelier-context-right{padding:7px}\n .model-atelier #atelierContextFields{grid-template-columns:minmax(0,1fr)}\n .model-atelier .atelier-context-header button{font-size:10px;padding:4px 6px}\n}\n"
JS = "\n// §E contextual workbench: optional companion to the original (unchanged) editing inspector.\nfunction atelierAdaptiveInstall(panel){\n window.__SWRLZ_CONTEXT_BOOT={entered:true,at:Date.now(),panel:!!panel};\n if(panel.querySelector('#atelierContextWorkbench'))return;\n const inspector=panel.querySelector('.atelier-inspector');\n const rail=panel.querySelector('#modelAtelierToolRail');\n const handle=panel.querySelector('.atelier-tool-handle');\n Object.assign(window.__SWRLZ_CONTEXT_BOOT,{inspector:!!inspector,rail:!!rail,handle:!!handle});\n if(!inspector||!rail||!handle)return;\n const sourceId=id=>document.getElementById('modelAtelier'+id);\n const GROUPS={\n  Meshes:[\n   ['Select & organize',['Parts','Add','Duplicate','Delete','Undo','Redo']],\n   ['Transform',['position0','position1','position2','rotation0','rotation1','rotation2','scale0','scale1','scale2']],\n   ['Material & shape',['Name','Kind','Material','Color']]\n  ],\n  Sculpt:[\n   ['Brush & falloff',['SculptBrushMode','SculptBrushFalloff','SculptBrushCurveEnabled','SculptBrushCurveValues','SculptBrushMirrorX','SculptBrushRadius','SculptBrushAmount','SculptBrushRadiusUnits','SculptBrushRadiusScreen','SculptBrushSurfaceMode','SculptBrushApply','SculptBrushUndoStroke']],\n   ['Brush placement',['SculptBrushCenter0','SculptBrushCenter1','SculptBrushCenter2','SculptBrushAxis0','SculptBrushAxis1','SculptBrushAxis2','SculptBrushPick','SculptBrushPreview','SculptBrushPreviewClear']],\n   ['Brush shape',['SculptBrushPlateau','SculptBrushTaper','SculptBrushLevel','SculptBrushHalf','SculptBrushYaw','SculptBrushPitch','SculptBrushSnap']],\n   ['Vertex editing',['SculptBrushIndices','SculptBrushIndicesApply','SculptBrushVertexToggle','SculptBrushVertexClear','SculptBrushVertexUndo']],\n   ['Sculpt resolution',['SculptDensityPreset','SculptBrushGridU','SculptBrushGridV','SculptDensityPreview','SculptBrushGridApply']]\n  ],\n  Lasso:[\n   ['Create region',['LassoName','LassoStart','LassoStartFreehand','LassoFinish','LassoCancel','LassoRegion']],\n   ['Pins & boundary',['LassoPinIndex','LassoPinXYZ0','LassoPinXYZ1','LassoPinXYZ2','LassoAddXYZ','LassoMoveXYZ','LassoInsertPin','LassoDeletePin']],\n   ['Group pins',['LassoGroupPins','LassoGroupDelta0','LassoGroupDelta1','LassoGroupDelta2','LassoGroupMove']],\n   ['Curve & grow',['LassoCurve','LassoCurveApply','LassoSegmentAmount','LassoSegmentMove']],\n   ['Paint mask',['LassoPaintMode','LassoPaintRadius','LassoPaintArm','LassoPaintXYZ0','LassoPaintXYZ1','LassoPaintXYZ2','LassoPaintAtXYZ','LassoPaintClear']],\n   ['Boolean masks',['LassoBooleanOp','LassoBooleanWith','LassoBooleanApply']],\n   ['Deform region',['LassoMorph','LassoFeather','LassoApplyMorph','LassoToggle','LassoDeleteRegion']]\n  ],\n  Face:[\n   ['UV face sheet',['FaceSheetShape','FaceSheetGridU','FaceSheetGridV','FaceSheetCropX','FaceSheetCropY','FaceSheetCropW','FaceSheetCropH','FaceSheetHeadDepth','FaceSheetApply']],\n   ['Facial landmarks',['FaceLandmarkPreset','FaceLandmarkPick','FaceLandmarkU','FaceLandmarkV','FaceLandmarkRadius','FaceLandmarkDepth','FaceLandmarkApply','FaceLandmarkRemove']],\n   ['Face contour',['FaceContourValues','FaceContourApply','FaceContourReset']],\n   ['Photographic cutout',['FaceCutoutPoints','FaceCutoutFeather','FaceCutoutStart','FaceCutoutFinish','FaceCutoutCancel','FaceCutoutApply','FaceCutoutClear']],\n   ['Profile calibration',['FaceProfileReference','FaceProfileOrigin','FaceProfileScale','FaceProfileDirection','FaceProfileCalibrate','FaceProfilePoint','FaceProfileLink','FaceProfileUnlink']],\n   ['Extrude faces',['FaceExtrudeFace','FaceExtrudeDepth','FaceExtrudePreview','FaceExtrudeApply']]\n  ],\n  Topology:[\n   ['Edge, vertex & face',['TopologyFace','TopologyEdge','TopologyVertex','TopologyDelta0','TopologyDelta1','TopologyDelta2','TopologySplit','TopologyMove','TopologyRemove']],\n   ['Adaptive local refinement',['AdaptiveTopologyCenter0','AdaptiveTopologyCenter1','AdaptiveTopologyCenter2','AdaptiveTopologyRadius','AdaptiveTopologyEdge','AdaptiveTopologyPreview','AdaptiveTopologyApply']],\n   ['Mesh audit',['TopologyAuditCheck','TopologyAuditRepair']],\n   ['Repair boundary',['BoundaryCapVertex','BoundaryCapPreview','BoundaryCapApply']],\n   ['LOD planning',['LODRatio','LODProtectUV','LODPreview','LODBake','LODOBJ']],\n   ['Runtime LOD',['RuntimeLODRatio','RuntimeLODDistance','RuntimeLODEnabled','RuntimeLODGenerate','RuntimeLODClear']],\n   ['UV mapping',['UVPlane','UVMirror','UVInspect','UVPreview','UVApply']]\n  ],\n  References:[\n   ['Image references',['ReferenceToggle','ReferenceFile','ReferenceAngle','ReferenceThumbnail','ReferencePin','ReferenceCollapse']],\n   ['Reference view',['ReferenceScale','ReferenceOpacity','ReferenceRotation','ReferenceCompare']],\n   ['Floating photos',['ReferenceFloat','ReferenceFloatAll','ReferenceCloseAll']]\n  ],\n  Motion:[\n   ['Model movement',['PoseFrame','PoseApply','PoseSave','MotionPlay','MotionPause','MotionStop']],\n   ['Pose & animation',['PosePreset','PoseFrameAdd','PoseFrameRemove','PosePreview']]\n  ],\n  Appearance:[\n   ['Portrait & anatomy',['PortraitFinish','HeadAnatomy','HeadSections','HeadApply']],\n   ['Detail & materials',['Material','Color','HDDetail','HDFinish']],\n   ['Model output',['Export','OBJ']]\n  ]\n };\n const GROUP_META={\n  Meshes:'Select mesh • transform • material',\n  Sculpt:'Brush placement • shape • density',\n  Lasso:'Select • paint • combine • deform',\n  Face:'Landmarks • cutout • UV face',\n  Topology:'Edges • LOD • UV • audit',\n  References:'Local images • floating views',\n  Motion:'Pose and animation controls',\n  Appearance:'Materials • detail • export'\n };\n const allGroupNames=Object.keys(GROUPS);\n const ui=document.createElement('section');\n ui.id='atelierContextWorkbench';ui.className='atelier-context-workbench';ui.hidden=true;\n ui.setAttribute('role','region');ui.setAttribute('aria-label','Contextual editing tool workbench');\n ui.innerHTML='<header class=\"atelier-context-header\"><strong>⠿ Context tools</strong><div><button type=\"button\" id=\"atelierContextNative\">Original inspector</button><button type=\"button\" id=\"atelierContextClose\" aria-label=\"Close contextual tools\">✕</button></div></header>'\n +'<div class=\"atelier-context-title\"><strong id=\"atelierContextGroupName\">Lasso</strong><span id=\"atelierContextPath\"></span></div>'\n +'<div class=\"atelier-context-body\"><div class=\"atelier-context-left\"><label for=\"atelierContextFind\">Find operation</label><input id=\"atelierContextFind\" type=\"search\" placeholder=\"Search tool cases\"><nav id=\"atelierContextOperations\" aria-label=\"Operations in selected tool\"></nav></div>'\n +'<div class=\"atelier-context-right\"><strong id=\"atelierContextOpName\"></strong><p id=\"atelierContextHelp\"></p><div id=\"atelierContextFields\"></div><div class=\"atelier-context-preset\"><button type=\"button\" id=\"atelierContextSavePreset\">Save my values</button><button type=\"button\" id=\"atelierContextApplyPreset\">Apply saved values</button></div><p id=\"atelierContextFeedback\" role=\"status\" aria-live=\"polite\"></p></div></div>';\n panel.append(ui);\n window.__SWRLZ_CONTEXT_BOOT.attached=true;\n const $=id=>ui.querySelector('#'+id);\n const opNav=$('atelierContextOperations'),fields=$('atelierContextFields'),feedback=$('atelierContextFeedback');\n let open=false,group='Lasso',selectedName='',drag=null;\n let catalog={};\n // Registry lookup is rebuilt against ACTUAL source nodes; missing features never generate fake actions.\n const unique=xs=>[...new Set(xs)];\n function isSupported(node){return node&&inspector.contains(node)&&(\n  node.matches('input:not([type=file]):not([type=hidden]),select,textarea,button'));}\n function detectGroup(id){\n  if(/^Lasso/.test(id))return 'Lasso';\n  if(/^Sculpt/.test(id)||/^Refine/.test(id))return 'Sculpt';\n  if(/^Face/.test(id)||/^Portrait/.test(id)||/^Head/.test(id))return 'Face';\n  if(/Topology|LOD|^UV|BoundaryCap|Audit/.test(id))return 'Topology';\n  if(/^Reference/.test(id))return 'References';\n  if(/Pose|Motion|Animation|Frame/.test(id))return 'Motion';\n  return 'Appearance';\n }\n function titleFromId(name){\n  return name.replace(/^modelAtelier/,'').replace(/([a-z])([A-Z])/g,'$1 $2').replace(/(\\D)(\\d+)$/,'$1 $2').trim();\n }\n function sourceNode(code){return sourceId(code);}\n function buildCatalog(){\n  catalog={};allGroupNames.forEach(k=>catalog[k]=[]);\n  const tracked=new Set();\n  for(const [category,entries] of Object.entries(GROUPS)){\n   for(const [name,ids] of entries){\n    const existing=unique(ids).filter(id=>isSupported(sourceNode(id)));\n    if(!existing.length)continue;\n    existing.forEach(id=>tracked.add('modelAtelier'+id));\n    catalog[category].push({name,ids:existing});\n   }\n  }\n  // Version-forward discovery: every eligible native fieldset with direct controls remains reachable.\n  for(const section of inspector.querySelectorAll('fieldset[id],section[id]')){\n   if(!section.id.startsWith('modelAtelier'))continue;\n   const untracked=[...section.querySelectorAll('input,select,textarea,button')]\n    .filter(n=>n.id&&isSupported(n)&&!tracked.has(n.id));\n   if(!untracked.length)continue;\n   const suffix=section.id.slice('modelAtelier'.length);\n   const category=detectGroup(suffix),ids=unique(untracked.map(n=>n.id.slice('modelAtelier'.length)));\n   catalog[category].push({name:titleFromId(section.id),ids});\n   untracked.forEach(n=>tracked.add(n.id));\n  }\n  // A fallback for native labeled inputs/buttons outside sections.\n  const extras=[...inspector.querySelectorAll('input[id],select[id],textarea[id],button[id]')]\n   .filter(n=>n.id.startsWith('modelAtelier')&&isSupported(n)&&!tracked.has(n.id)&&!['ImportFile'].includes(n.id.slice(12)));\n  const byGroup={};\n  extras.forEach(n=>{const suffix=n.id.slice('modelAtelier'.length);const cat=detectGroup(suffix);\n    (byGroup[cat]??=[]).push(suffix);});\n  for(const [cat,ids] of Object.entries(byGroup))catalog[cat].push({name:'Additional '+cat.toLowerCase()+' controls',ids});\n }\n function operations(){buildCatalog();return catalog[group]||[];}\n function nativeVisible(n){return !!n&&!n.disabled&&!n.closest('[hidden]');}\n function nativeLabel(n){\n  const label=n.closest('label');\n  let str=(label?.textContent||n.getAttribute('aria-label')||n.getAttribute('title')||n.textContent||'').trim();\n  if(n.matches('button'))str=n.textContent.trim()||n.getAttribute('aria-label')||titleFromId(n.id);\n  if(!str||str.length>85)str=titleFromId(n.id);\n  return str.replace(/\\s+/g,' ').slice(0,75);\n }\n function currentOp(){return operations().find(x=>x.name===selectedName)||operations()[0];}\n function read(n){return n.matches('input[type=checkbox],input[type=radio]')?n.checked:n.value;}\n function assign(n,val){\n  if(!nativeVisible(n))return false;\n  if(n.matches('input[type=checkbox],input[type=radio]')){n.checked=!!val;}\n  else if(n.tagName==='SELECT'){\n   if(![...n.options].some(o=>o.value===String(val)))return false;\n   n.value=String(val);\n  }else{\n   if(n.type==='number'&&(!Number.isFinite(Number(val))||String(val)===''))return false;\n   n.value=String(val);\n  }\n  // Respect native HTML input constraints, especially stored presets.\n  if(typeof n.checkValidity==='function'&&!n.checkValidity())return false;\n  n.dispatchEvent(new Event('input',{bubbles:true}));\n  n.dispatchEvent(new Event('change',{bubbles:true}));\n  return true;\n }\n const presetsKey='swyrlz-at-context-presets-v1';\n function presets(){try{const raw=JSON.parse(localStorage.getItem(presetsKey)||'{}');return raw&&typeof raw==='object'&&!Array.isArray(raw)?raw:{}}catch(_){return {}}}\n function presetId(){return group+'/'+selectedName;}\n function setFeedback(s){feedback.textContent=s;}\n function createProxy(native){\n  const row=document.createElement('div');row.className='atelier-context-field';\n  const name=document.createElement('label');name.textContent=nativeLabel(native);row.append(name);\n  const available=nativeVisible(native);\n  if(native.tagName==='BUTTON'){\n   const b=document.createElement('button');b.type='button';b.textContent='Run · '+name.textContent;\n   b.disabled=!available;\n   b.addEventListener('click',()=>{if(!nativeVisible(native)){setFeedback('Select an eligible mesh or enable this control in the original editor.');return;}\n    native.click();setFeedback('Triggered the original '+name.textContent+' operation.');renderFields();});\n   row.replaceChildren(b);return row;\n  }\n  let proxy;\n  if(native.tagName==='SELECT'){\n   proxy=document.createElement('select');\n   for(const o of native.options){const next=document.createElement('option');next.value=o.value;next.textContent=o.textContent;proxy.append(next);}\n   proxy.value=native.value;\n  }else if(native.tagName==='TEXTAREA'){\n   proxy=document.createElement('textarea');proxy.rows=Math.max(2,Math.min(native.rows||3,6));proxy.value=native.value;\n  }else{\n   proxy=document.createElement('input');\n   proxy.type=['number','range','checkbox','color','text','search'].includes(native.type)?native.type:'text';\n   for(const attr of ['min','max','step','maxlength'])if(native.hasAttribute(attr))proxy.setAttribute(attr,native.getAttribute(attr));\n   if(proxy.type==='checkbox')proxy.checked=native.checked;else proxy.value=native.value;\n  }\n  proxy.id='atelierContextProxy_'+native.id;\n  name.htmlFor=proxy.id;proxy.disabled=!available;\n  proxy.addEventListener('change',()=>{\n   if(assign(native,read(proxy)))setFeedback('Applied to native editor: '+name.textContent);\n   else setFeedback('This control is unavailable for the current selection.');\n   if(native.matches('input[type=checkbox],input[type=radio]'))proxy.checked=native.checked;\n   else proxy.value=native.value;\n  });\n  row.append(proxy);return row;\n }\n function renderFields(){\n  const query=$('atelierContextFind').value.trim().toLowerCase();\n  const op=operations().find(o=>o.name===selectedName&&(!query||o.name.toLowerCase().includes(query)||o.ids.some(id=>titleFromId('modelAtelier'+id).toLowerCase().includes(query))));\n  fields.replaceChildren();setFeedback('');\n  $('atelierContextOpName').textContent=op?.name||'No compatible tools';\n  $('atelierContextHelp').textContent=op?'These fields and actions operate the original §E controls. Changes apply when edited.':'Select a supported mesh or workspace to make operations available.';\n  if(!op)return;\n  for(const id of op.ids){\n   const n=sourceNode(id);\n   if(!isSupported(n))continue;\n   fields.append(createProxy(n));\n  }\n  if(!fields.children.length){const p=document.createElement('p');p.textContent='No editable native controls available in this category.';fields.append(p);}\n  $('atelierContextPath').textContent='Model Atelier → '+group+' → '+op.name;\n  const saved=presets()[presetId()];\n  $('atelierContextApplyPreset').disabled=!saved;\n }\n function showOps(){\n  opNav.replaceChildren();\n  const q=$('atelierContextFind').value.toLowerCase().trim();\n  const ops=operations().filter(o=>o.name.toLowerCase().includes(q)||o.ids.some(id=>titleFromId('modelAtelier'+id).toLowerCase().includes(q)));\n  if(!ops.some(o=>o.name===selectedName))selectedName=ops[0]?.name||'';\n  for(const op of ops){\n   const b=document.createElement('button');b.type='button';b.textContent=op.name;\n   b.className='atelier-context-op';b.setAttribute('aria-pressed',String(op.name===selectedName));\n   b.addEventListener('click',()=>{selectedName=op.name;showOps();});\n   opNav.append(b);\n  }\n  renderFields();\n }\n function pickGroup(name){\n  if(!allGroupNames.includes(name))return;\n  group=name;$('atelierContextGroupName').textContent=name+' tools';\n  $('atelierContextFind').value='';selectedName='';showOps();\n }\n function setOpen(value){\n  open=!!value;ui.hidden=!open;\n  panel.classList.toggle('atelier-context-active',open);\n  handle.querySelector('#atelierContextToggle')?.setAttribute('aria-pressed',String(open));\n  if(open){pickGroup(group);}\n }\n const activate=document.createElement('button');activate.type='button';activate.id='atelierContextToggle';\n activate.textContent='◫ Context';activate.title='Secondary operation list and tool-specific settings';\n activate.setAttribute('aria-controls','atelierContextWorkbench');activate.setAttribute('aria-pressed','false');\n activate.addEventListener('click',()=>setOpen(!open));\n handle.querySelector('strong')?.after(activate);\n $('atelierContextClose').addEventListener('click',()=>setOpen(false));\n $('atelierContextNative').addEventListener('click',()=>{setOpen(false);handle.scrollIntoView({block:'nearest'});});\n $('atelierContextFind').addEventListener('input',showOps);\n $('atelierContextSavePreset').addEventListener('click',()=>{\n  const op=currentOp();if(!op)return;\n  const list=op.ids.map(id=>sourceNode(id)).filter(n=>isSupported(n)&&n.tagName!=='BUTTON');\n  const content={};list.forEach(n=>{content[n.id]=read(n);});\n  try{const obj=presets();obj[presetId()]=content;localStorage.setItem(presetsKey,JSON.stringify(obj));\n   renderFields();setFeedback('Saved '+list.length+' input values for '+op.name+'. Apply explicitly when needed.');}\n  catch(_){setFeedback('Preset storage is unavailable in this browser.');}\n });\n $('atelierContextApplyPreset').addEventListener('click',()=>{\n  const obj=presets()[presetId()];if(!obj)return;\n  let count=0;\n  for(const [id,value] of Object.entries(obj)){\n   if(!/^modelAtelier[A-Za-z0-9]+$/.test(id))continue;\n   const n=document.getElementById(id);\n   if(isSupported(n)&&n.tagName!=='BUTTON'&&assign(n,value))count++;\n  }\n  renderFields();setFeedback('Explicitly applied '+count+' saved values through native controls.');\n });\n // Keep the original vertical rail and make its selected category drive the companion.\n rail.addEventListener('click',event=>{\n  const b=event.target.closest('button');if(!b||!rail.contains(b))return;\n  const label=b.textContent.trim();\n  if(allGroupNames.includes(label)&&open)pickGroup(label);\n });\n for(const name of ['References','Motion','Appearance']){\n  if([...rail.querySelectorAll('button')].some(b=>b.textContent.trim()===name))continue;\n  const b=document.createElement('button');b.type='button';b.textContent=name;\n  b.setAttribute('aria-label','Open '+name+' editing tools');\n  b.setAttribute('aria-controls','atelierContextWorkbench');\n  b.addEventListener('click',()=>{if(!open)setOpen(true);pickGroup(name);});\n  rail.append(b);\n }\n // Inspector may change selection after native edits; refresh only displayed proxies.\n inspector.addEventListener('change',event=>{\n  if(!open||!event.target.id?.startsWith('modelAtelier'))return;\n  const op=currentOp();if(op?.ids.some(id=>'modelAtelier'+id===event.target.id))renderFields();\n });\n const header=ui.querySelector('.atelier-context-header');\n header.addEventListener('pointerdown',e=>{\n  if(e.button!==0||e.target.closest('button,input'))return;\n  const r=ui.getBoundingClientRect();drag={id:e.pointerId,x:e.clientX,y:e.clientY,left:r.left,top:r.top};\n  try{header.setPointerCapture(e.pointerId)}catch(_){}\n  e.preventDefault();\n });\n header.addEventListener('pointermove',e=>{\n  if(!drag||e.pointerId!==drag.id)return;\n  const left=Math.max(4,Math.min(innerWidth-ui.offsetWidth-4,drag.left+e.clientX-drag.x));\n  const top=Math.max(4,Math.min(innerHeight-75,drag.top+e.clientY-drag.y));\n  ui.style.left=left+'px';ui.style.top=top+'px';ui.style.right='auto';ui.style.bottom='auto';\n  e.preventDefault();\n });\n for(const name of ['pointerup','pointercancel'])header.addEventListener(name,e=>{if(drag&&drag.id===e.pointerId)drag=null;});\n const originalClose=panel.querySelector('#modelAtelierClose');\n originalClose?.addEventListener('click',()=>setOpen(false));\n // This API is only UI inspection/navigation, not a parallel source of editing authority.\n window.SWYRL_E_CONTEXT=Object.freeze({groups:()=>Object.fromEntries(allGroupNames.map(k=>[k,(catalog[k]||[]).map(v=>v.name)])),open:()=>open,current:()=>({group,operation:selectedName})});\n buildCatalog();\n}\n// Native Model Atelier may be installed after initial module evaluation; observe once,\n// then disconnect immediately on successful attachment (no perpetual polling).\n(function atelierContextWatchForDock(){\n if(typeof MutationObserver!=='function'||!document.body)return;\n const install=()=>{\n  const panel=document.getElementById('modelAtelierPanel');\n  if(!panel||!panel.querySelector('#modelAtelierToolRail'))return false;\n  if(!panel.querySelector('#atelierContextWorkbench'))atelierAdaptiveInstall(panel);\n  return !!panel.querySelector('#atelierContextWorkbench');\n };\n window.__SWRLZ_CONTEXT_WATCH={registered:true};\n const observer=new MutationObserver(()=>{\n  if(install()){observer.disconnect();window.__SWRLZ_CONTEXT_WATCH.attached=true;}\n });\n observer.observe(document.body,{childList:true,subtree:true});\n queueMicrotask(()=>{if(install()){observer.disconnect();window.__SWRLZ_CONTEXT_WATCH.attached=true;}});\n})();\n"
def apply(html):
    target='    atelierToolDockInstall(panel);\n'
    assert html.count(target)==1,'Expected sealed v11.60 tool dock insertion'
    assert html.count('SWYRL_ENGINE_DEPLOY_MARKER: V11_60_FLOATING_MODEL_ATELIER_DOCK')==1
    assert 'function atelierAdaptiveInstall(panel)' not in html
    assert html.count('</head>')>=1
    html=html.replace('const ModelAtelier=(()=>{', JS+'\nconst ModelAtelier=(()=>{',1)
    html=html.replace(target,target+'    atelierAdaptiveInstall(panel);\n',1)
    html=html.replace('</head>','<style id="atelierContextWorkbenchStyle">'+CSS+'</style>\n</head>',1)
    return html
